import { mkdir } from 'node:fs/promises'
import { Agent } from '@mastra/core/agent'
import { Memory } from '@mastra/memory'
import { LibSQLStore } from '@mastra/libsql'

// 为每个独立入口准备本地存储，保留线程和运行记录。
export async function createStorage (name) {
  await mkdir('./data', { recursive: true })
  return new LibSQLStore({ id: name, url: `file:./data/${name}.db` })
}

// 创建核查助手，并允许各入口补充本节需要的能力。
export function createAssistant (storage, options = {}) {
  return new Agent({
    id: 'policy-reviewer',
    name: '制度核查助手',
    instructions: '核查给出的制度材料，列明结论、依据与待确认事项。只使用提供的事实，不编造核查结果。',
    model: 'vercel/openai/gpt-6.1-sol',
    memory: new Memory({ storage, options: { lastMessages: 12 } }),
    ...options
  })
}

import { Mastra } from '@mastra/core'
import { createDurableAgent } from '@mastra/core/agent/durable'
import { createAssistant, createStorage } from './assistant.js'

// 在本地存储上注册一个可按运行标识观察的助手。
const storage = await createStorage('durable')
// 配置本入口使用的核查助手。
const reviewer = createDurableAgent({ agent: createAssistant(storage) })
// 注册助手及其共用的运行服务。
const mastra = new Mastra({ agents: { reviewer }, storage })
// 保留运行清理函数。
let cleanup

try {
  const run = await reviewer.stream('材料：住宿每晚不超过 500 元，超出须事先书面批准。请核查一晚 560 元但没有批准记录的申请。', {
    memory: { thread: crypto.randomUUID(), resource: 'demo-user' }
  })
  cleanup = run.cleanup
  console.log('运行标识：', run.runId)
  console.log('核查结果：', await run.output.text)
} finally {
  await mastra.shutdown()
  cleanup?.()
  await storage.close()
}

